using System.Net;
using System.Text.Json;
using Microsoft.AspNetCore.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;
using Relay.Core.ActivityHealth;
using Relay.Core.Calendar;
using Relay.Core.Normality;
using Relay.Core.Queries;

namespace Relay.Api.Tests;

public sealed class ThrowawayContractTests(WebApplicationFactory<Program> factory) : IClassFixture<WebApplicationFactory<Program>>
{
    [Theory]
    [InlineData("?type=ALL")]
    [InlineData("?type=Call_Received")]
    [InlineData("?type=")]
    [InlineData("?type=foo")]
    [InlineData("?type=1")]
    [InlineData("?week=")]
    [InlineData("?week=2026-7-20")]
    public async Task InvalidQueryReturnsValidationProblem(string query)
    {
        using var client = factory.CreateClient();
        var response = await client.GetAsync(new Uri($"/api/accounts/6/activity-health{query}", UriKind.Relative), TestContext.Current.CancellationToken);
        var body = await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken);
        Console.WriteLine($"{query} -> {(int)response.StatusCode} {body}");
        response.StatusCode.ShouldBe(HttpStatusCode.BadRequest);
        body.ShouldContain("\"errors\"");
    }

    [Theory]
    [InlineData("")]
    [InlineData("?type=all")]
    [InlineData("?type=call_received&week=2026-07-20")]
    [InlineData("?type=lead_created")]
    [InlineData("?type=appointment_set")]
    public async Task ValidQueryPassesValidation(string query)
    {
        using var client = factory.CreateClient();
        var response = await client.GetAsync(new Uri($"/api/accounts/6/activity-health{query}", UriKind.Relative), TestContext.Current.CancellationToken);
        Console.WriteLine($"{query} -> {(int)response.StatusCode}");
        response.StatusCode.ShouldBe(HttpStatusCode.InternalServerError);
    }

    [Fact]
    public void ReportSerialisesAsSection52()
    {
        var jsonOptions = factory.Services.GetRequiredService<IOptions<JsonOptions>>().Value.SerializerOptions;
        var report = new ActivityHealthReport(
            new AccountListItem(6, "Metro Collision Centers", "America/New_York"),
            ActivityType.All,
            new WeekRange(new DateOnly(2026, 7, 20), new DateOnly(2026, 7, 26)),
            new DateTime(2026, 7, 27, 22, 20, 34, DateTimeKind.Utc),
            new DateOnly(2026, 7, 20),
            new DateOnly(2026, 1, 26),
            8,
            4,
            new SeriesHealth(87, new Baseline(8, 72.5, 30, 134), HealthStatus.Normal, 0.53),
